str def hardRejectReason(boolean:renting, boolean:illegal, int:overdueMonths, boolean:safetyViolation) {
    if (renting) {
        return "RENTING";
    } else if (illegal) {
        return "ILLEGAL";
    } else if (overdueMonths > 6) {
        return "OVERDUE";
    } else if (safetyViolation) {
        return "SAFETY";
    } else {
        return "PASS";
    }
}


int def propertyWaiverPercent(str:householdType, boolean:vacant) {
    if (householdType == "SUBSISTENCE") {
        return 100;
    } else if (householdType == "MARTYR") {
        return 100;
    } else if (householdType == "DISABLED") {
        return 100;
    } else if (householdType == "LOW_INCOME") {
        return 60;
    } else if (householdType == "ELDERLY_ALONE") {
        return 50;
    } else if (vacant) {
        return 30;
    } else {
        return 0;
    }
}


int def parkingWaiverPercent(str:householdType) {
    if (householdType == "SUBSISTENCE") {
        return 100;
    } else if (householdType == "MARTYR") {
        return 100;
    } else if (householdType == "DISABLED") {
        return 100;
    } else if (householdType == "LOW_INCOME") {
        return 50;
    } else {
        return 0;
    }
}


double def qualifiedArea(double:size, double:perCapita, int:family, str:householdType) {
    double cap = 15.0;
    if (householdType == "SUBSISTENCE") {
        cap = 30.0;
    } else if (householdType == "MARTYR") {
        cap = 30.0;
    } else if (householdType == "DISABLED") {
        cap = 30.0;
    } else if (householdType == "ELDERLY_ALONE") {
        cap = 30.0;
    } else if (householdType == "LOW_INCOME") {
        cap = 20.0;
    }
    if (perCapita <= cap) {
        return size;
    }
    double limit = cap * family;
    if (size < limit) {
        return size;
    } else {
        return limit;
    }
}
